mapper.select:
SELECT a.user_id id,
CONCAT_WS('_', b.job_number, a.user_name) `name`, b.department_id pId, b.department_id departmentId, b.email,
CONCAT_WS('_', a.job_number, a.user_name) `name`, a.department_id pId, a.department_id departmentId, a.email,
'isPeople' folderType, 0 isParent, a.phone
FROM sys_eve_user_staff a
,tenant_user b
LENGTH(a.user_id) > 0 AND a.user_id != ''
AND b.company_id = #{companyId}
AND a.company_id = #{companyId}
AND b.department_id = #{departmentId}
AND a.department_id = #{departmentId}
AND a.user_id != #{userId}
AND LENGTH(b.email) > 0 AND b.email != ''
AND LENGTH(a.email) > 0 AND a.email != ''
AND b.tenant_id = #{tenantId} AND b.staff_id = a.id
